import torch
import torch.nn as nn
import torch.nn.functional as F

def aug(image, preprocess, mixture_depth, aug_severity):
	aug_list = augmentations.augmentations
	image_aug = image.copy()
	depth = mixture_depth if mixture_depth > 0 else np.random.randint(1, 4)
	for _ in range(depth):
		op = np.random.choice(aug_list)
		image_aug = op(image_aug, aug_severity)
	image_aug = preprocess(image_aug)
	return image_aug

class AugMaxDataset(torch.utils.data.Dataset):
	def __init__(self, dataset, preprocess, mixture_width=3, mixture_depth=-1, aug_severity=3, aug_fn=aug):
		self.dataset = dataset
		self.preprocess = preprocess
		self.mixture_width = mixture_width
		self.mixture_depth = mixture_depth
		self.aug_severity = aug_severity
		self.img_tuple_num = 2
		self.aug_fn = aug_fn

	def __getitem__(self, i):
		x, y = self.dataset[i]

		img_tuples = []
		for _ in range(self.img_tuple_num):
			img_tuple = [self.preprocess(x)]
			for _ in range(self.mixture_width):
				img_tuple.append(
					self.aug_fn(x, self.preprocess, self.mixture_depth, self.aug_severity)
				)
			img_tuples.append(img_tuple)
		return img_tuples, y

	def __len__(self):
		return len(self.dataset)

class AugMaxModule(nn.Module):
	def __init__(self, device='cuda'):
		super(AugMaxModule, self).__init__()
		self.device = device

	def forward(self, xs, m, q):
		x_ori = xs[0]
		w = torch.nn.functional.softmax(q, dim=1)

		N = x_ori.size()[0]

		x_mix = torch.zeros_like(x_ori).to(self.device)
		for i, x_aug in enumerate(xs[1:]):
			wi = w[:,i].view((N,1,1,1)).expand_as(x_aug)
			x_mix += wi * x_aug

		m = m.view((N,1,1,1)).expand_as(x_ori)
		x_mix = (1-m) * x_ori + m * x_mix

		return x_mix

class DualBatchNorm2d(nn.Module):
    def __init__(self, num_features):
        super(DualBatchNorm2d, self).__init__()
        self.bn = nn.ModuleList([nn.BatchNorm2d(num_features), nn.BatchNorm2d(num_features)])
        self.num_features = num_features
        self.ignore_model_profiling = True

        self.route = 'M'

    def forward(self, input):
        idx = ['M', 'A'].index(self.route)
        y = self.bn[idx](input)
        return y

class DuBIN(nn.Module):
    def __init__(self, planes, ratio=0.5):
        super(DuBIN, self).__init__()
        self.half = int(planes * ratio)
        self.IN = nn.InstanceNorm2d(self.half, affine=True)
        self.BN = DualBatchNorm2d(planes - self.half)

    def forward(self, x):
        split = torch.split(x, self.half, 1)
        out1 = self.IN(split[0].contiguous())
        out2 = self.BN(split[1].contiguous())
        out = torch.cat((out1, out2), 1)
        return out

def linf_clamp(x, _min, _max):
	idx = x.data < _min
	x.data[idx] = _min[idx]
	idx = x.data > _max
	x.data[idx] = _max[idx]

	return x

class AugMaxAttack():
	def __init__(self, steps=10, alpha=0.1, loss_fn=None, targeted=False):
		self.steps = steps
		self.alpha = alpha
		self.targeted = targeted
		self.loss_fn = loss_fn if loss_fn else nn.CrossEntropyLoss(reduction="sum")

	def attack(self, augmax_model, model, xs, labels=None, targets=None, noisy=False, grad_noise_level=0.1, random_level=False, device='cuda'):
		model.eval()

		mixture_width = len(xs) - 1
		N = xs[0].size()[0]

		m_adv = torch.rand(N).to(device)
		m_adv = torch.clamp(m_adv, 0, 1)
		m_adv.requires_grad=True

		q_adv = torch.rand((N,mixture_width), requires_grad=True).to(device)

		x_adv = augmax_model(xs, m_adv , q_adv)

		if random_level:
			alpha = self.alpha * np.random.choice([1,0.5,0.2,0.1])
		else:
			alpha = self.alpha

		for t in range(self.steps):
			logits_adv = model(x_adv)
			if self.targeted:
				loss_adv = - self.loss_fn(logits_adv, targets)
			else:
				loss_adv = self.loss_fn(logits_adv, labels)
			grad_m_adv, grad_q_adv = torch.autograd.grad(loss_adv, [m_adv, q_adv], only_inputs=True)
			m_adv.data.add_(alpha * torch.sign(grad_m_adv.data))
			if noisy:
				m_adv.data.add_(grad_noise_level * alpha * torch.rand(grad_m_adv.data.size()).to(device))
			m_adv = torch.clamp(m_adv, 0, 1)
			q_adv.data.add_(alpha * torch.sign(grad_q_adv.data))
			if noisy:
				q_adv.data.add_(grad_noise_level * alpha * torch.rand(grad_q_adv.data.size()).to(device))
			x_adv = augmax_model(xs, m_adv , q_adv)

		return x_adv, m_adv, q_adv

class FriendlyAugMaxAttack():
	def __init__(self, steps=10, alpha=0.1, tau=1, loss_fn=None, targeted=False):
		self.steps = steps
		self.alpha = alpha
		self.tau = tau
		self.targeted = targeted
		self.loss_fn = loss_fn if loss_fn else nn.CrossEntropyLoss(reduction="sum")

	def attack(self, augmax_model, model, xs, labels, targets=None, verbose=False, noisy=False, grad_noise_level=0.1, random_level=False, device='cuda'):
		model.eval()

		mixture_width = len(xs) - 1
		N = xs[0].size()[0]

		m_adv = torch.rand(N).to(device)
		m_adv = torch.clamp(m_adv, 0, 1)
		m_adv.requires_grad=True

		q_adv = torch.rand((N,mixture_width), requires_grad=True).to(device)

		x_adv = augmax_model(xs, m_adv , q_adv)

		if random_level:
			alpha = self.alpha * np.random.choice([1,0.5,0.2,0.1])
		else:
			alpha = self.alpha

		if self.targeted:
			budget = (torch.ones(len(targets)) * self.tau).to(device)
		else:
			budget = (torch.ones(len(labels)) * self.tau).to(device)

		for t in range(self.steps):
			logits_adv = model(x_adv)
			pred = logits_adv.max(1, keepdim=True)[1]

			incorrect_sample_idx = (pred.squeeze() != labels)
			havent_used_up_budget_idx = (budget != 0)
			budget[torch.logical_and(incorrect_sample_idx, havent_used_up_budget_idx)] -= 1
			attack_sample_idx = (budget > 0).detach().cpu().numpy()
			if np.sum(attack_sample_idx) == 0:
				if verbose:
					print('Early stopping at step %d' % t)
				break
			if self.targeted:
				loss_adv = - self.loss_fn(logits_adv, targets)
			else:
				loss_adv = self.loss_fn(logits_adv, labels)
			grad_m_adv, grad_q_adv = torch.autograd.grad(loss_adv, [m_adv, q_adv], only_inputs=True)
			grad_m_adv.data[~attack_sample_idx].zero_()
			grad_q_adv.data[~attack_sample_idx].zero_()
			m_adv.data.add_(alpha * torch.sign(grad_m_adv.data))
			if noisy:
				m_adv.data.add_(grad_noise_level * alpha * torch.rand(grad_m_adv.data.size()).to(device))
			m_adv = torch.clamp(m_adv, 0, 1)
			q_adv.data.add_(alpha * torch.sign(grad_q_adv.data))
			if noisy:
				q_adv.data.add_(grad_noise_level * alpha * torch.rand(grad_q_adv.data.size()).to(device))
			x_adv = augmax_model(xs, m_adv, q_adv)

		return x_adv, m_adv, q_adv

